import { Package, ClipboardList, LayoutDashboard, CalendarDays, Layers3, Compass, ChartNoAxesCombined, Plus, Search, ChevronLeft, ChevronRight, ChevronDown, ArrowUpRight, ArrowRight, Flower2, Download, Upload, X, Copy, Trash2, Check, Clock3, MoreHorizontal, List, Calendar, CheckCircle2, Mail, Send, FlaskConical, BookOpenCheck, MessageCircleQuestion, Users, Inbox, Library as LibraryIcon, Receipt } from 'lucide-react';
import { calendarCsv, certainties, contentStatuses, dateLabel, emptyEntry, isoToday, newsletterCampaignStatuses, parseCalendarCsv, parseProjectCsv, parseScenarioCsv, projectCsv, projectCsvExample, projectStatuses, scenarioCsv, scenarioCsvExample, scenarioStatuses, stages, type Entry, type EntryInput, type Kind } from '../lib/model';
